import java.util.*;
public class Main {public static void main(String[]a){int n=100000;List<Integer> values=new ArrayList<>();for(int i=0;i<n;i++)values.add(i);long t=System.nanoTime();long sum=0;for(int i=0;i<values.size();i++)sum+=values.get(i);long listTime=System.nanoTime()-t;int[] array=new int[n];for(int i=0;i<n;i++)array[i]=i;t=System.nanoTime();long sum2=0;for(int v:array)sum2+=v;long arrayTime=System.nanoTime()-t;System.out.println("List sum="+sum+" ns="+listTime);System.out.println("Array sum="+sum2+" ns="+arrayTime);System.out.println("Choose based on measured workload; avoid claiming one timing is universal.");}}
